import{_ as a,o as s,c as t,a0 as i}from"./chunks/framework.DoRPXVp_.js";const g=JSON.parse('{"title":"Local Test-README Script Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-08-local-test-readme-script-design.md","filePath":"superpowers/specs/2026-05-08-local-test-readme-script-design.md"}'),l={name:"superpowers/specs/2026-05-08-local-test-readme-script-design.md"};function o(n,e,r,c,d,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="local-test-readme-script-design" tabindex="-1">Local Test-README Script Design <a class="header-anchor" href="#local-test-readme-script-design" aria-label="Permalink to &quot;Local Test-README Script Design&quot;">​</a></h1><p><strong>Date:</strong> 2026-05-08 <strong>Status:</strong> Approved</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>The <code>test-readme-script.yml</code> CI workflow validates README CLI commands end-to-end, but can only run in GitHub Actions. Every code change requires merging to master or waiting for a PR build to see results. Developers need a way to run the same test locally without rebuilding images unnecessarily.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Extract the CI workflow logic into <code>scripts/test-readme.sh</code> so it can be run locally with <code>bash scripts/test-readme.sh</code>, while the CI workflow calls the same script — one source of truth for both environments.</p><h2 id="script-scripts-test-readme-sh" tabindex="-1">Script: <code>scripts/test-readme.sh</code> <a class="header-anchor" href="#script-scripts-test-readme-sh" aria-label="Permalink to &quot;Script: \`scripts/test-readme.sh\`&quot;">​</a></h2><h3 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to &quot;Flags&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--force-build</code></td><td>Force rebuild of both images even if local versions exist</td></tr></tbody></table><h3 id="image-strategy" tabindex="-1">Image Strategy <a class="header-anchor" href="#image-strategy" aria-label="Permalink to &quot;Image Strategy&quot;">​</a></h3><p>Both <code>lattice-k3s</code> and <code>lattice</code> agent images follow the same resolution order:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. K3S_IMAGE / AGENT_IMAGE env var set? → use it (CI passes pr-N tag)</span></span>
<span class="line"><span>2. --force-build? → build/pull fresh</span></span>
<span class="line"><span>3. Local image exists (lattice-k3s:local / lattice:local)? → use it</span></span>
<span class="line"><span>4. Otherwise → build lattice-k3s from source / pull lattice from GHCR</span></span></code></pre></div><p>Local builds are tagged <code>:local</code> to distinguish from registry images:</p><ul><li><code>lattice-k3s:local</code> — built from <code>deploy/k3s/Dockerfile</code></li><li><code>lattice:local</code> — built locally if available, otherwise <code>ghcr.io/alatticeio/lattice:latest</code></li></ul><h3 id="cleanup-behaviour" tabindex="-1">Cleanup Behaviour <a class="header-anchor" href="#cleanup-behaviour" aria-label="Permalink to &quot;Cleanup Behaviour&quot;">​</a></h3><ul><li><strong>Success</strong> → automatically remove all containers and the <code>wf-test-net</code> bridge network</li><li><strong>Failure</strong> → leave containers running; print debugging instructions:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=== TEST FAILED ===</span></span>
<span class="line"><span>Containers preserved for debugging:</span></span>
<span class="line"><span>  docker logs lattice-k3s</span></span>
<span class="line"><span>  docker logs wf-agent-a</span></span>
<span class="line"><span>  docker logs wf-agent-b</span></span>
<span class="line"><span>To clean up manually:</span></span>
<span class="line"><span>  docker rm -f lattice-k3s wf-agent-a wf-agent-b</span></span>
<span class="line"><span>  docker network rm wf-test-net</span></span></code></pre></div><h3 id="script-flow" tabindex="-1">Script Flow <a class="header-anchor" href="#script-flow" aria-label="Permalink to &quot;Script Flow&quot;">​</a></h3><p>Steps map 1:1 to the existing workflow steps:</p><ol><li>Parse arguments (<code>--force-build</code>)</li><li>Resolve images (per strategy above)</li><li>Start <code>lattice-k3s</code> container (<code>--privileged -p 8080:8080</code>)</li><li>Wait for K8s API + CRDs + latticed <code>:8080</code> ready</li><li>Login → obtain <code>AUTH_TOKEN</code></li><li>Set <code>LATTICE=&quot;docker run --rm --network host -e LATTICE_AUTH_TOKEN=... &lt;image&gt;&quot;</code></li><li>Step 1: <code>workspace add</code> / <code>workspace list</code></li><li>Step 2: <code>token create</code> / <code>token list</code> → extract <code>TOKEN</code></li><li>Wait for operator to create workspace namespace</li><li>Step 3: start <code>wf-agent-a</code> and <code>wf-agent-b</code> on <code>wf-test-net</code> bridge</li><li>Wait for both agents to register (≥2 nodes)</li><li>Wait for LatticePeer IP allocation</li><li>Step 4: <code>policy allow-all</code> / <code>policy add</code> / <code>policy list</code></li><li>Step 5: <code>lattice status</code> inside containers + ping A→B</li><li>Step 6: <code>token remove</code> / <code>policy remove</code> / <code>workspace remove</code></li><li>Cleanup (success only)</li></ol><h2 id="ci-integration" tabindex="-1">CI Integration <a class="header-anchor" href="#ci-integration" aria-label="Permalink to &quot;CI Integration&quot;">​</a></h2><p><code>test-readme-script.yml</code> is simplified to call the script directly:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Run README test script&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bash scripts/test-readme.sh</span></span></code></pre></div><p>The <code>K3S_IMAGE</code> and <code>AGENT_IMAGE</code> env vars remain in the workflow and are read by the script, allowing CI to pass PR-specific tags (<code>pr-N</code>) without any changes to the script logic.</p><p>The existing <code>build-k3s-image.yml</code> workflow continues to build and push images on PRs and master pushes — the test script just consumes whatever image is available.</p><h2 id="local-usage" tabindex="-1">Local Usage <a class="header-anchor" href="#local-usage" aria-label="Permalink to &quot;Local Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># First run — builds lattice-k3s:local from source (~5 min)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-readme.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Subsequent runs — reuses lattice-k3s:local (~1 min startup)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-readme.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># After changing deploy/k3s/ or cmd/latticed/ — force rebuild</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-readme.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-build</span></span></code></pre></div><h2 id="files-changed" tabindex="-1">Files Changed <a class="header-anchor" href="#files-changed" aria-label="Permalink to &quot;Files Changed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td><code>scripts/test-readme.sh</code></td><td>New — extracted + enhanced from workflow</td></tr><tr><td><code>.github/workflows/test-readme-script.yml</code></td><td>Simplified to call the script</td></tr></tbody></table>`,29)])])}const u=a(l,[["render",o]]);export{g as __pageData,u as default};
